14	ThreadPool::ThreadPool(std::string thread_name_prefix, const uint32_t min_size, const uint32_t max_size)
15	    : thread_name_prefix_(std::move(thread_name_prefix)),
16	      is_stopped_(false),
17	      min_thrd_num_(min_size < 1U ? 1U : min_size),
18	      max_thrd_num_(max_size < min_thrd_num_ ? min_thrd_num_ : max_size) {
19	  idle_thrd_num_ = min_thrd_num_;
20	  total_thrd_num_ = min_thrd_num_;
21	  busy_thrd_num_ = 0U;
22	
23	  for (uint32_t i = 0U; i < min_thrd_num_; ++i) {
24	    pool_.emplace_back(&ThreadFunc, this, i, false, nullptr);
25	  }
26	  HIXL_LOGI("[ThreadPool] created, name:%s, min_size:%u, max_size:%u, core_threads:%u", thread_name_prefix_.c_str(),
27	            min_thrd_num_, max_thrd_num_, min_thrd_num_);
28	}
