31	using ThreadTask = std::function<void()>;
32	
33	class ThreadPool {
34	 public:
35	  explicit ThreadPool(std::string thread_name_prefix, const uint32_t min_size = 4U, const uint32_t max_size = 4U);
36	  ~ThreadPool();
37	  void Destroy();
38	
39	  template <class Func, class... Args>
40	  auto commit(Func &&func, Args &&...args) -> std::future<decltype(func(args...))> {
41	    HIXL_LOGD("[ThreadPool:%s] commit task enter", thread_name_prefix_.c_str());
42	    using retType = decltype(func(args...));
43	    std::future<retType> fail_future;
44	    if (is_stopped_.load()) {
45	      HIXL_LOGE(ge::FAILED, "[ThreadPool:%s] has been stopped", thread_name_prefix_.c_str());
46	      return fail_future;
47	    }
48	
49	    const auto bindFunc = std::bind(std::forward<Func>(func), std::forward<Args>(args)...);
50	    const auto task = MakeShared<std::packaged_task<retType()>>(bindFunc);
51	    if (task == nullptr) {
52	      HIXL_LOGE(ge::FAILED, "[ThreadPool:%s] make shared failed", thread_name_prefix_.c_str());
53	      return fail_future;
54	    }
55	    std::future<retType> future = task->get_future();
56	    size_t task_queue_size = 0U;
57	    {
58	      const std::lock_guard<std::mutex> lock{m_lock_};
59	      tasks_.emplace([task]() { (*task)(); });
60	      task_queue_size = tasks_.size();
61	    }
62	
63	    uint32_t idle_num = idle_thrd_num_.load();
64	    uint32_t busy_num = busy_thrd_num_.load();
65	    uint32_t total_num = total_thrd_num_.load();
66	    if (idle_num == 0U && task_queue_size > 0U && total_num < max_thrd_num_) {
67	      HIXL_LOGI("[ThreadPool:%s] scaling up, idle:%u, busy:%u, total:%u, max:%u, tasks:%zu",
68	                thread_name_prefix_.c_str(), idle_num, busy_num, total_num, max_thrd_num_, task_queue_size);
69	      AddTemporaryThread();
70	    }
71	
72	    cond_var_.notify_one();
73	    HIXL_LOGD("[ThreadPool:%s] commit task end, idle:%u, busy:%u, total:%u, tasks:%zu", thread_name_prefix_.c_str(),
74	              idle_num, busy_num, total_num, task_queue_size);
75	    return future;
76	  }
77	
78	  static void ThreadFunc(ThreadPool *const thread_pool, uint32_t thread_idx, bool is_temporary,
79	                         std::atomic<bool> *finished_flag);
80	
