82	  void AddTemporaryThread();
83	  void SetThreadName(const std::string &thread_type, uint32_t thread_idx) const;
84	  void LogTempThreadExit(const char *reason, uint32_t thread_idx) const;
85	  bool PopTask(std::function<void()> &task);
86	  void CleanupFinishedTempThreads();
87	
88	  struct TempThreadEntry {
89	    std::thread thread;
90	    std::atomic<bool> finished{false};
91	  };
92	
93	  std::string thread_name_prefix_;
94	  std::vector<std::thread> pool_;
95	  std::list<TempThreadEntry> temp_threads_;
96	  std::queue<ThreadTask> tasks_;
97	  std::mutex m_lock_;
98	  std::condition_variable cond_var_;
99	  std::atomic<bool> is_stopped_;
100	  std::atomic<uint32_t> idle_thrd_num_;
101	  std::atomic<uint32_t> busy_thrd_num_;
102	  std::atomic<uint32_t> total_thrd_num_;
103	  uint32_t min_thrd_num_;
104	  uint32_t max_thrd_num_;
105	};
