22	constexpr uint32_t kTestTimeoutMs = 400U;
23	constexpr uint32_t kTaskDurationMs = 100U;
24	
25	class ThreadPoolTest : public ::testing::Test {
26	 protected:
27	  struct BlockingTaskContext {
28	    std::mutex mtx;
29	    std::condition_variable cv;
30	    std::atomic<uint32_t> concurrent_count{0};
31	    std::atomic<uint32_t> max_concurrent{0};
32	    std::atomic<uint32_t> tasks_started{0};
33	    std::atomic<bool> release_tasks{false};
34	  };
35	
36	  void SetUp() override {}
37	  void TearDown() override {}
38	
39	  void WaitForTasks(std::atomic<uint32_t> &counter, uint32_t expected, uint32_t timeout_ms = kTestTimeoutMs) {
40	    auto start = std::chrono::steady_clock::now();
41	    while (counter.load() < expected) {
42	      auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - start);
43	      if (elapsed.count() >= static_cast<int64_t>(timeout_ms)) {
44	        break;
45	      }
46	      std::this_thread::sleep_for(std::chrono::milliseconds(2));
47	    }
48	  }
49	
50	  std::function<void()> CreateBlockingTask(BlockingTaskContext &ctx) {
51	    return [&]() {
52	      uint32_t current = ctx.concurrent_count.fetch_add(1) + 1U;
53	      if (current > ctx.max_concurrent.load()) {
54	        ctx.max_concurrent.store(current);
55	      }
56	      ctx.tasks_started.fetch_add(1);
57	      ctx.cv.notify_one();
58	
59	      std::unique_lock<std::mutex> lock(ctx.mtx);
60	      ctx.cv.wait(lock, [&]() { return ctx.release_tasks.load(); });
61	
62	      ctx.concurrent_count.fetch_sub(1);
63	    };
64	  }
65	
66	  void ReleaseTasks(BlockingTaskContext &ctx) {
67	    ctx.release_tasks.store(true);
68	    ctx.cv.notify_all();
69	  }
70	};
71	
72	TEST_F(ThreadPoolTest, TasksExecutedSuccessfully) {
73	  ThreadPool pool("test_exec", 2U, 4U);
74	
75	  std::atomic<uint32_t> counter{0};
76	  const uint32_t task_count = 10U;
77	
78	  for (uint32_t i = 0; i < task_count; ++i) {
79	    pool.commit([&]() { counter.fetch_add(1); });
80	  }
81	
82	  WaitForTasks(counter, task_count);
83	  EXPECT_EQ(counter.load(), task_count);
84	}
