98	    ctx.cv.wait_for(lock, std::chrono::milliseconds(100), [&]() { return ctx.tasks_started.load() >= 2U; });
99	  }
100	
101	  pool.commit(blocking_task);
102	  pool.commit(blocking_task);
103	
104	  {
105	    std::unique_lock<std::mutex> lock(ctx.mtx);
106	    ctx.cv.wait_for(lock, std::chrono::milliseconds(100), [&]() { return ctx.tasks_started.load() >= 3U; });
107	  }
108	
109	  ReleaseTasks(ctx);
110	  WaitForTasks(ctx.tasks_started, 4U, 200U);
111	  EXPECT_GE(ctx.max_concurrent.load(), 3U);
112	}
