131	  }
132	
133	  std::this_thread::sleep_for(std::chrono::milliseconds(50));
134	  ReleaseTasks(ctx);
135	  WaitForTasks(ctx.tasks_started, 5U, 200U);
136	  EXPECT_LE(ctx.max_concurrent.load(), 3U);
137	}
138	
139	TEST_F(ThreadPoolTest, TemporaryThreadExitsAfterTask) {
140	  ThreadPool pool("test_temp", 1U, 3U);
